// ============================================================
// Shared domain types — imported by services and the router.
// No business logic lives here.
// ============================================================

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO-8601
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO-8601
}

// ---- Input shapes ----

export interface CreateUserInput {
  name: string;
  email: string;
}

export interface UpdateUserInput {
  name?: string;
  email?: string;
}

export interface CreateProjectInput {
  name: string;
  description: string;
}

export interface UpdateProjectInput {
  name?: string;
  description?: string;
}

export interface CreateTaskInput {
  title: string;
  description: string;
  projectId: string;
}

export interface UpdateTaskInput {
  title?: string;
  description?: string;
}

export interface CreateCommentInput {
  taskId: string;
  authorId: string;
  body: string;
}

// ---- Service result helpers ----

export type ServiceResult<T> =
  | { ok: true; data: T }
  | { ok: false; status: number; error: string };

export function ok<T>(data: T): ServiceResult<T> {
  return { ok: true, data };
}

export function fail(status: number, error: string): ServiceResult<never> {
  return { ok: false, status, error };
}

// ============================================================
// Event Bus — in-memory publish/subscribe.
// Services never import each other; they communicate solely
// through events published here.
// ============================================================

type EventCallback = (payload: unknown) => void;

class EventBus {
  private readonly listeners = new Map<string, EventCallback[]>();

  /** Register a handler for a named event. */
  subscribe(event: string, callback: EventCallback): void {
    const existing = this.listeners.get(event) ?? [];
    existing.push(callback);
    this.listeners.set(event, existing);
  }

  /** Dispatch an event to every registered handler synchronously. */
  publish(event: string, payload: unknown): void {
    const handlers = this.listeners.get(event) ?? [];
    for (const handler of handlers) {
      try {
        handler(payload);
      } catch (err) {
        // Isolate subscriber errors so a failing handler doesn't
        // prevent other handlers from running.
        console.error(`[EventBus] Handler error for event "${event}":`, err);
      }
    }
  }
}

// Singleton shared across the whole process.
export const eventBus = new EventBus();

// ---- Well-known event names (avoids magic strings) ----------

export const Events = {
  TASK_ASSIGNED: 'task.assigned',
  TASK_STATUS_CHANGED: 'task.statusChanged',
  COMMENT_ADDED: 'comment.added',
} as const;

// ---- Typed payload interfaces --------------------------------

export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: string;
  newStatus: string;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

// ============================================================
// User Service
// Owns the in-memory user store.
// No imports from other services; no event publishing.
// ============================================================

import { randomUUID } from 'crypto';
import {
  User,
  CreateUserInput,
  UpdateUserInput,
  ServiceResult,
  ok,
  fail,
} from '../types.js';

class UserService {
  private readonly store = new Map<string, User>();

  listUsers(): ServiceResult<User[]> {
    return ok(Array.from(this.store.values()));
  }

  getUser(id: string): ServiceResult<User> {
    const user = this.store.get(id);
    if (!user) return fail(404, `User "${id}" not found`);
    return ok(user);
  }

  createUser(input: CreateUserInput): ServiceResult<User> {
    if (!input.name?.trim()) return fail(400, 'Field "name" is required');
    if (!input.email?.trim()) return fail(400, 'Field "email" is required');

    const user: User = {
      id: randomUUID(),
      name: input.name.trim(),
      email: input.email.trim(),
    };
    this.store.set(user.id, user);
    return ok(user);
  }

  updateUser(id: string, input: UpdateUserInput): ServiceResult<User> {
    const existing = this.store.get(id);
    if (!existing) return fail(404, `User "${id}" not found`);

    const updated: User = {
      ...existing,
      ...(input.name !== undefined ? { name: input.name.trim() } : {}),
      ...(input.email !== undefined ? { email: input.email.trim() } : {}),
    };
    this.store.set(id, updated);
    return ok(updated);
  }

  deleteUser(id: string): ServiceResult<void> {
    if (!this.store.has(id)) return fail(404, `User "${id}" not found`);
    this.store.delete(id);
    return ok(undefined);
  }
}

export const userService = new UserService();

// ============================================================
// Project Service
// Owns the in-memory project store.
// No imports from other services; no event publishing.
// ============================================================

import { randomUUID } from 'crypto';
import {
  Project,
  CreateProjectInput,
  UpdateProjectInput,
  ServiceResult,
  ok,
  fail,
} from '../types.js';

class ProjectService {
  private readonly store = new Map<string, Project>();

  listProjects(): ServiceResult<Project[]> {
    return ok(Array.from(this.store.values()));
  }

  getProject(id: string): ServiceResult<Project> {
    const project = this.store.get(id);
    if (!project) return fail(404, `Project "${id}" not found`);
    return ok(project);
  }

  createProject(input: CreateProjectInput): ServiceResult<Project> {
    if (!input.name?.trim()) return fail(400, 'Field "name" is required');
    if (input.description === undefined || input.description === null)
      return fail(400, 'Field "description" is required');

    const project: Project = {
      id: randomUUID(),
      name: input.name.trim(),
      description: input.description,
      memberIds: [],
    };
    this.store.set(project.id, project);
    return ok(project);
  }

  updateProject(id: string, input: UpdateProjectInput): ServiceResult<Project> {
    const existing = this.store.get(id);
    if (!existing) return fail(404, `Project "${id}" not found`);

    const updated: Project = {
      ...existing,
      ...(input.name !== undefined ? { name: input.name.trim() } : {}),
      ...(input.description !== undefined
        ? { description: input.description }
        : {}),
    };
    this.store.set(id, updated);
    return ok(updated);
  }

  deleteProject(id: string): ServiceResult<void> {
    if (!this.store.has(id)) return fail(404, `Project "${id}" not found`);
    this.store.delete(id);
    return ok(undefined);
  }

  addMember(projectId: string, userId: string): ServiceResult<Project> {
    const project = this.store.get(projectId);
    if (!project) return fail(404, `Project "${projectId}" not found`);

    if (!project.memberIds.includes(userId)) {
      const updated: Project = {
        ...project,
        memberIds: [...project.memberIds, userId],
      };
      this.store.set(projectId, updated);
      return ok(updated);
    }
    return ok(project); // already a member — idempotent
  }

  removeMember(projectId: string, userId: string): ServiceResult<Project> {
    const project = this.store.get(projectId);
    if (!project) return fail(404, `Project "${projectId}" not found`);

    const updated: Project = {
      ...project,
      memberIds: project.memberIds.filter((id) => id !== userId),
    };
    this.store.set(projectId, updated);
    return ok(updated);
  }
}

export const projectService = new ProjectService();

// ============================================================
// Task Service
// Owns the in-memory task store.
// Publishes events to the Event Bus; never imports other services.
// ============================================================

import { randomUUID } from 'crypto';
import {
  Task,
  TaskStatus,
  CreateTaskInput,
  UpdateTaskInput,
  ServiceResult,
  ok,
  fail,
} from '../types.js';
import {
  eventBus,
  Events,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
} from '../event-bus.js';

// Forward-only status transitions (ADR constraint #4).
const VALID_TRANSITIONS: Record<TaskStatus, TaskStatus | null> = {
  'todo': 'in-progress',
  'in-progress': 'done',
  'done': null,
};

class TaskService {
  private readonly store = new Map<string, Task>();

  listByProject(projectId: string): ServiceResult<Task[]> {
    const tasks = Array.from(this.store.values()).filter(
      (t) => t.projectId === projectId,
    );
    return ok(tasks);
  }

  getTask(id: string): ServiceResult<Task> {
    const task = this.store.get(id);
    if (!task) return fail(404, `Task "${id}" not found`);
    return ok(task);
  }

  createTask(input: CreateTaskInput): ServiceResult<Task> {
    if (!input.title?.trim()) return fail(400, 'Field "title" is required');
    if (input.description === undefined || input.description === null)
      return fail(400, 'Field "description" is required');
    if (!input.projectId?.trim())
      return fail(400, 'Field "projectId" is required');

    const task: Task = {
      id: randomUUID(),
      title: input.title.trim(),
      description: input.description,
      status: 'todo',
      assigneeId: null,
      projectId: input.projectId.trim(),
    };
    this.store.set(task.id, task);
    return ok(task);
  }

  updateTask(id: string, input: UpdateTaskInput): ServiceResult<Task> {
    const existing = this.store.get(id);
    if (!existing) return fail(404, `Task "${id}" not found`);

    const updated: Task = {
      ...existing,
      ...(input.title !== undefined ? { title: input.title.trim() } : {}),
      ...(input.description !== undefined
        ? { description: input.description }
        : {}),
    };
    this.store.set(id, updated);
    return ok(updated);
  }

  deleteTask(id: string): ServiceResult<void> {
    if (!this.store.has(id)) return fail(404, `Task "${id}" not found`);
    this.store.delete(id);
    return ok(undefined);
  }

  changeStatus(id: string, newStatus: TaskStatus): ServiceResult<Task> {
    const task = this.store.get(id);
    if (!task) return fail(404, `Task "${id}" not found`);

    const allowedNext = VALID_TRANSITIONS[task.status];
    if (allowedNext !== newStatus) {
      return fail(
        400,
        `Invalid status transition: "${task.status}" → "${newStatus}". ` +
          `Allowed next status: ${allowedNext ?? '(none — task is already done)'}`,
      );
    }

    const oldStatus = task.status;
    const updated: Task = { ...task, status: newStatus };
    this.store.set(id, updated);

    // Notify subscribers — only if there is an assignee to notify.
    if (updated.assigneeId) {
      const payload: TaskStatusChangedPayload = {
        taskId: updated.id,
        taskTitle: updated.title,
        assigneeId: updated.assigneeId,
        oldStatus,
        newStatus,
      };
      eventBus.publish(Events.TASK_STATUS_CHANGED, payload);
    }

    return ok(updated);
  }

  assignTask(id: string, assigneeId: string): ServiceResult<Task> {
    const task = this.store.get(id);
    if (!task) return fail(404, `Task "${id}" not found`);

    const updated: Task = { ...task, assigneeId };
    this.store.set(id, updated);

    const payload: TaskAssignedPayload = {
      taskId: updated.id,
      taskTitle: updated.title,
      assigneeId,
    };
    eventBus.publish(Events.TASK_ASSIGNED, payload);

    return ok(updated);
  }
}

export const taskService = new TaskService();

// ============================================================
// Comment Service
// Owns the in-memory comment store.
// Publishes events to the Event Bus; never imports other services.
//
// NOTE: The router passes taskTitle and authorName when calling
// createComment so that this service can publish a rich event
// without querying other services directly.
// ============================================================

import { randomUUID } from 'crypto';
import {
  Comment,
  CreateCommentInput,
  ServiceResult,
  ok,
  fail,
} from '../types.js';
import { eventBus, Events, CommentAddedPayload } from '../event-bus.js';

// Extended input accepted internally (router enriches the raw HTTP body).
export interface EnrichedCreateCommentInput extends CreateCommentInput {
  taskTitle: string;
  authorName: string;
}

class CommentService {
  private readonly store = new Map<string, Comment>();

  listByTask(taskId: string): ServiceResult<Comment[]> {
    const comments = Array.from(this.store.values())
      .filter((c) => c.taskId === taskId)
      .sort(
        (a, b) =>
          new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime(),
      );
    return ok(comments);
  }

  getComment(id: string): ServiceResult<Comment> {
    const comment = this.store.get(id);
    if (!comment) return fail(404, `Comment "${id}" not found`);
    return ok(comment);
  }

  createComment(input: EnrichedCreateCommentInput): ServiceResult<Comment> {
    if (!input.taskId?.trim()) return fail(400, 'Field "taskId" is required');
    if (!input.authorId?.trim())
      return fail(400, 'Field "authorId" is required');
    if (!input.body?.trim()) return fail(400, 'Field "body" is required');

    const comment: Comment = {
      id: randomUUID(),
      taskId: input.taskId.trim(),
      authorId: input.authorId.trim(),
      body: input.body.trim(),
      createdAt: new Date().toISOString(),
    };
    this.store.set(comment.id, comment);

    const payload: CommentAddedPayload = {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle: input.taskTitle,
      authorId: comment.authorId,
      authorName: input.authorName,
    };
    eventBus.publish(Events.COMMENT_ADDED, payload);

    return ok(comment);
  }

  deleteComment(id: string): ServiceResult<void> {
    if (!this.store.has(id)) return fail(404, `Comment "${id}" not found`);
    this.store.delete(id);
    return ok(undefined);
  }
}

export const commentService = new CommentService();

// ============================================================
// Notification Service
// Owns the in-memory notification store.
// Subscribes to Event Bus events; never imports other services.
// ============================================================

import { randomUUID } from 'crypto';
import { Notification, ServiceResult, ok, fail } from '../types.js';
import {
  eventBus,
  Events,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
  CommentAddedPayload,
} from '../event-bus.js';

class NotificationService {
  private readonly store = new Map<string, Notification>();

  // ---- Public API ------------------------------------------

  listForUser(userId: string): ServiceResult<Notification[]> {
    const notes = Array.from(this.store.values())
      .filter((n) => n.userId === userId)
      .sort(
        (a, b) =>
          new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
      );
    return ok(notes);
  }

  markRead(id: string): ServiceResult<Notification> {
    const note = this.store.get(id);
    if (!note) return fail(404, `Notification "${id}" not found`);

    const updated: Notification = { ...note, read: true };
    this.store.set(id, updated);
    return ok(updated);
  }

  // ---- Private helpers -------------------------------------

  private create(userId: string, message: string): void {
    const note: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(note.id, note);
  }

  // ---- Event Bus subscriptions -----------------------------

  private registerSubscriptions(): void {
    eventBus.subscribe(Events.TASK_ASSIGNED, (raw) => {
      const payload = raw as TaskAssignedPayload;
      this.create(
        payload.assigneeId,
        `You have been assigned to task "${payload.taskTitle}" (${payload.taskId}).`,
      );
    });

    eventBus.subscribe(Events.TASK_STATUS_CHANGED, (raw) => {
      const payload = raw as TaskStatusChangedPayload;
      if (!payload.assigneeId) return;
      this.create(
        payload.assigneeId,
        `Task "${payload.taskTitle}" status changed from "${payload.oldStatus}" to "${payload.newStatus}".`,
      );
    });

    eventBus.subscribe(Events.COMMENT_ADDED, (raw) => {
      const payload = raw as CommentAddedPayload;
      this.create(
        payload.authorId,
        `Your comment on task "${payload.taskTitle}" was recorded (comment ${payload.commentId}).`,
      );
    });
  }
}

// Instantiate and wire up event subscriptions immediately.
const notificationService = new NotificationService();
// Access private method via casting to register subscriptions at startup.
(notificationService as unknown as { registerSubscriptions(): void }).registerSubscriptions();

export { notificationService };

// ============================================================
// Notification Service
// Owns the in-memory notification store.
// Subscribes to Event Bus events; never imports other services.
