  assert('Notification.read is true', (markRead.body as Record<string, boolean>).read === true);

  // 404 on unknown notification
  const badNotif = await request('PUT', '/notifications/no-such-id/read');
  assert('Mark unknown notification → 404', badNotif.status === 404);

  // ── 9. Edge Cases & Cleanup ───────────────────────────────
  console.log('\n── 9. Edge Cases & Cleanup ──────────────────────────');

  // Delete a task
  const task3 = await request<Record<string, string>>('POST', '/tasks', {
    title: 'Temp task',
    description: 'Will be deleted',
    projectId,
  });
  const task3Id = task3.body.id;
  const deleteTask = await request('DELETE', `/tasks/${task3Id}`);
  assert('Delete task → 204', deleteTask.status === 204);
  assert('Deleted task returns 404', (await request('GET', `/tasks/${task3Id}`)).status === 404);

  // Delete a project
  const tempProj = await request<Record<string, string>>('POST', '/projects', {
    name: 'Temp',
    description: 'Temp',
  });
  const tempProjId = tempProj.body.id;
  const deleteProj = await request('DELETE', `/projects/${tempProjId}`);
  assert('Delete project → 204', deleteProj.status === 204);

  // Delete a user
  const tempUser = await request<Record<string, string>>('POST', '/users', {
    name: 'Temp',
    email: 'temp@x.com',
  });
  const tempUserId = tempUser.body.id;
  const deleteUser = await request('DELETE', `/users/${tempUserId}`);
  assert('Delete user → 204', deleteUser.status === 204);

  // Unknown route
  const unknown = await request('GET', '/foobar');
  assert('Unknown route → 404', unknown.status === 404);

  // Missing required field
  const badUser = await request('POST', '/users', { email: 'no-name@x.com' });
  assert('Missing name field → 400', badUser.status === 400);

  // ── Summary ───────────────────────────────────────────────
  console.log('\n─────────────────────────────────────────────────────');
  console.log(`Results: ${passed} passed, ${failed} failed`);
  if (failed === 0) {
    console.log('🎉 All tests passed!\n');
  } else {
    console.log('⚠️  Some tests failed — see ❌ lines above.\n');
  }
}

