    console.error('[Demo Server] Error:', err);
    res.writeHead(500);
    res.end(JSON.stringify({ error: 'Internal server error' }));
  });
});

server.listen(PORT, async () => {
  try {
    await runDemo();
  } catch (err) {
    console.error('Demo failed with uncaught error:', err);
  } finally {
    server.close(() => {
      process.exit(failed > 0 ? 1 : 0);
    });
  }
});

